const allowed = new Set(["ToolSearch","TodoWrite","mcp__bb-bridge__bb_update_plan","mcp__bb-bridge__workspace_read","mcp__bb-bridge__workspace_write","mcp__bb-bridge__workspace_edit","mcp__bb-bridge__workspace_glob","mcp__bb-bridge__workspace_grep","mcp__bb-bridge__workspace_exec","mcp__bb-bridge__workspace_diff"]);
const block = (reason) => {
  process.stderr.write(reason + "\n");
  process.exit(2);
};
process.on("uncaughtException", () => block("account-workers guard failed; tool blocked"));
let input = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => (input += chunk));
process.stdin.on("end", () => {
  let name;
  try {
    name = JSON.parse(input).tool_name;
  } catch {
    block("account-workers guard could not read the tool call; tool blocked");
